import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [email, setEmail] = useState('');
  const [motDePasse, setMotDePasse] = useState('');
  const [connecte, setConnecte] = useState(false);
  const [user, setUser] = useState(null);
  const [token, setToken] = useState('');
  const [message, setMessage] = useState('');
  
  // États pour la gestion
  const [ongletActif, setOngletActif] = useState('dashboard');
  const [articles, setArticles] = useState([]);
  const [ventes, setVentes] = useState([]);
  const [beneficeTotal, setBeneficeTotal] = useState(0);
  const [nouvelArticle, setNouvelArticle] = useState({
    reference: '',
    nom: '',
    description: '',
    prix_achat: '',
    prix_vente: '',
    quantite_stock: '',
    taille: '',
    couleur: ''
  });

  // Charger les données quand connecté
  useEffect(() => {
    if (connecte) {
      chargerArticles();
    }
  }, [connecte]);

  const chargerArticles = async () => {
    try {
      const response = await axios.get('http://127.0.0.1:5000/api/articles', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setArticles(response.data);
      
      // Calculer le bénéfice potentiel
      if (user && user.role === 'admin') {
        const benefice = response.data.reduce((total, art) => 
          total + ((art.prix_vente - art.prix_achat) * art.quantite_stock), 0);
        setBeneficeTotal(benefice);
      }
    } catch (error) {
      console.error('Erreur chargement articles:', error);
    }
  };

  const handleLogin = async () => {
    try {
      const response = await axios.post('http://127.0.0.1:5000/api/auth/login', {
        email: email,
        mot_de_passe: motDePasse
      });
      
      setUser(response.data.user);
      setToken(response.data.token);
      setConnecte(true);
      setMessage('');
      
      localStorage.setItem('token', response.data.token);
      localStorage.setItem('user', JSON.stringify(response.data.user));
      
    } catch (error) {
      setMessage('Email ou mot de passe incorrect');
    }
  };

  const handleLogout = () => {
    setConnecte(false);
    setUser(null);
    setToken('');
    setEmail('');
    setMotDePasse('');
    setOngletActif('dashboard');
    setArticles([]);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
  };

  const handleAjouterArticle = async () => {
    try {
      await axios.post('http://127.0.0.1:5000/api/articles', nouvelArticle, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('✅ Article ajouté avec succès !');
      setNouvelArticle({
        reference: '',
        nom: '',
        description: '',
        prix_achat: '',
        prix_vente: '',
        quantite_stock: '',
        taille: '',
        couleur: ''
      });
      chargerArticles();
    } catch (error) {
      alert('❌ Erreur lors de l\'ajout de l\'article');
      console.error(error);
    }
  };

  const handleSupprimerArticle = async (id) => {
    if (window.confirm('Voulez-vous vraiment supprimer cet article ?')) {
      try {
        await axios.delete(`http://127.0.0.1:5000/api/articles/${id}`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        alert('✅ Article supprimé !');
        chargerArticles();
      } catch (error) {
        alert('❌ Erreur lors de la suppression');
      }
    }
  };

  // Page de connexion
  if (!connecte) {
    return (
      <div style={styles.loginContainer}>
        <div style={styles.loginBox}>
          <h1>🏪 Gestion Boutique</h1>
          <h2>Connexion</h2>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
          />
          <input
            type="password"
            placeholder="Mot de passe"
            value={motDePasse}
            onChange={(e) => setMotDePasse(e.target.value)}
            style={styles.input}
          />
          <button onClick={handleLogin} style={styles.button}>
            Se connecter
          </button>
          {message && <p style={styles.error}>{message}</p>}
          <p style={styles.info}>Démo: admin@boutique.com / admin123</p>
        </div>
      </div>
    );
  }

  // Application principale
  return (
    <div style={styles.appContainer}>
      {/* Barre de navigation */}
      <nav style={styles.navbar}>
        <h2 style={styles.logo}>🏪 Boutique</h2>
        <div style={styles.navButtons}>
          <button 
            onClick={() => setOngletActif('dashboard')} 
            style={ongletActif === 'dashboard' ? styles.navButtonActive : styles.navButton}
          >
            📊 Tableau de bord
          </button>
          
          {user.role === 'admin' && (
            <button 
              onClick={() => setOngletActif('articles')} 
              style={ongletActif === 'articles' ? styles.navButtonActive : styles.navButton}
            >
              📦 Articles
            </button>
          )}
          
          <button 
            onClick={() => setOngletActif('vente')} 
            style={ongletActif === 'vente' ? styles.navButtonActive : styles.navButton}
          >
            💰 Vente
          </button>
        </div>
        <div style={styles.userInfo}>
          <span style={styles.userName}>{user.nom} ({user.role})</span>
          <button onClick={handleLogout} style={styles.logoutButton}>
            Déconnexion
          </button>
        </div>
      </nav>

      {/* Contenu principal */}
      <main style={styles.mainContent}>
        {ongletActif === 'dashboard' && (
          <div>
            <h2>📊 Tableau de bord</h2>
            <div style={styles.statsGrid}>
              <div style={styles.statCard}>
                <h3>📦 Articles en stock</h3>
                <p style={styles.statNumber}>{articles.length}</p>
              </div>
              
              {user.role === 'admin' && (
                <>
                  <div style={styles.statCard}>
                    <h3>💰 Valeur du stock</h3>
                    <p style={styles.statNumber}>
                      {articles.reduce((total, art) => total + (art.prix_vente * (art.quantite_stock || 0)), 0).toFixed(0)} FCFA
                    </p>
                  </div>
                  <div style={styles.statCard}>
                    <h3>📈 Bénéfice potentiel</h3>
                    <p style={styles.statNumber}>
                      {beneficeTotal.toFixed(0)} FCFA
                    </p>
                  </div>
                </>
              )}
            </div>
            
            <div style={styles.welcomeCard}>
              <h3>👋 Bienvenue {user.nom} !</h3>
              <p>Vous êtes connecté en tant que : <strong>{user.role}</strong></p>
              {user.role === 'admin' ? (
                <p>✅ Vous avez accès à toutes les fonctionnalités, y compris la gestion du stock.</p>
              ) : (
                <p>⚠️ Vous n'avez pas accès aux informations de stock (prix d'achat, quantités).</p>
              )}
            </div>
          </div>
        )}

        {ongletActif === 'articles' && user.role === 'admin' && (
          <div>
            <h2>📦 Gestion des articles</h2>
            
            {/* Formulaire d'ajout */}
            <div style={styles.formCard}>
              <h3>➕ Ajouter un nouvel article</h3>
              <div style={styles.formGrid}>
                <input
                  placeholder="Référence *"
                  value={nouvelArticle.reference}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, reference: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Nom *"
                  value={nouvelArticle.nom}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, nom: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Prix d'achat (FCFA) *"
                  type="number"
                  value={nouvelArticle.prix_achat}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, prix_achat: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Prix de vente (FCFA) *"
                  type="number"
                  value={nouvelArticle.prix_vente}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, prix_vente: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Quantité en stock *"
                  type="number"
                  value={nouvelArticle.quantite_stock}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, quantite_stock: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Taille (ex: M, L, XL)"
                  value={nouvelArticle.taille}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, taille: e.target.value})}
                  style={styles.input}
                />
                <input
                  placeholder="Couleur"
                  value={nouvelArticle.couleur}
                  onChange={(e) => setNouvelArticle({...nouvelArticle, couleur: e.target.value})}
                  style={styles.input}
                />
              </div>
              <button onClick={handleAjouterArticle} style={styles.button}>
                ✅ Ajouter l'article
              </button>
            </div>

            {/* Liste des articles */}
            <div style={styles.tableCard}>
              <h3>📋 Articles en stock ({articles.length})</h3>
              {articles.length === 0 ? (
                <p style={{textAlign: 'center', color: '#999'}}>Aucun article pour le moment</p>
              ) : (
                <div style={{overflowX: 'auto'}}>
                  <table style={styles.table}>
                    <thead>
                      <tr>
                        <th>Référence</th>
                        <th>Nom</th>
                        <th>Prix d'achat</th>
                        <th>Prix de vente</th>
                        <th>Stock</th>
                        <th>Bénéfice/unité</th>
                        <th>Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {articles.map(article => (
                        <tr key={article.id}>
                          <td>{article.reference}</td>
                          <td>{article.nom}</td>
                          <td>{article.prix_achat} FCFA</td>
                          <td>{article.prix_vente} FCFA</td>
                          <td style={{
                            color: article.quantite_stock <= 5 ? 'red' : 'green',
                            fontWeight: 'bold'
                          }}>
                            {article.quantite_stock}
                          </td>
                          <td>{(article.prix_vente - article.prix_achat).toFixed(0)} FCFA</td>
                          <td>
                            <button 
                              onClick={() => handleSupprimerArticle(article.id)}
                              style={styles.deleteButton}
                            >
                              🗑️
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        )}

        {ongletActif === 'vente' && (
          <div style={{textAlign: 'center'}}>
            <h2>💰 Nouvelle vente</h2>
            <div style={styles.welcomeCard}>
              <h3>📝 Fonctionnalité en préparation</h3>
              <p>La gestion des ventes sera ajoutée dans la prochaine étape.</p>
              <p>Pour l'instant, vous pouvez gérer vos articles.</p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

